let x = 5;
const pos = document.querySelector("#pos");

function move(dx) {
  x = Math.min(10, Math.max(0, x + dx));
  pos.textContent = `Position: ${x}`;
}

document.querySelector("#left").addEventListener("click", () => move(-1));
